import math

def find_order(a, m):
    if math.gcd(a, m) != 1:
        return None # Should not happen here

    k = 1
    while True:
        if pow(a, k, m) == 1:
            return k
        k += 1

# Step 1: Find L_16 = ord_16(3)
L_16 = find_order(3, 16)
print(f"L_16 = {L_16}")

# Step 2: Find L_625 = ord_625(3)
L_625 = find_order(3, 625)
print(f"L_625 = {L_625}")

# Step 3: Calculate L = lcm(L_16, L_625)
def lcm(a, b):
    return abs(a * b) // math.gcd(a, b)

L = lcm(L_16, L_625)
print(f"L = lcm({L_16}, {L_625}) = {L}")
